            snapshot = plannerResult.snapshot;
            for (const nodeId of plannerResult.addedNodeIds) {
                executableNodeIds.add(nodeId);
            }
            if (plannerResult.plannersRan > 0) {
                frontierKey = "";
            }
            frontierKey = await this.emitFrontierChangedIfNeeded(snapshot, executableNodeIds, frontierKey, options.abortSignal);
            if (areExecutableNodesComplete(snapshot.graph, executableNodeIds, Boolean(this.plannerRunner)) &&
                active.size === 0) {
                await this.eventLog.emitEvent(snapshot, "executor_completed", {
                    message: `${options.phase} scheduler completed.`,
                    phase: options.phase,
                    signal: options.abortSignal,
                });
